                                <h2 id="endpoints-PUTapi-v1-internships--internship_id-">PUT /api/v1/internships/{internship}
Replaces the whole posting, but only if the policy allows it.</h2>

<p>
</p>



<span id="example-requests-PUTapi-v1-internships--internship_id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PUT \
    "http://localhost:8000/api/v1/internships/16" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"data\": {
        \"attributes\": {
            \"title\": \"b\",
            \"product\": \"architecto\",
            \"description\": \"Eius et animi quos velit et.\",
            \"status\": \"closed\"
        },
        \"relationships\": {
            \"user\": {
                \"data\": {
                    \"id\": 16
                }
            },
            \"author\": {
                \"data\": {
                    \"id\": 16
                }
            }
        }
    }
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/internships/16"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "data": {
        "attributes": {
            "title": "b",
            "product": "architecto",
            "description": "Eius et animi quos velit et.",
            "status": "closed"
        },
        "relationships": {
            "user": {
                "data": {
                    "id": 16
                }
            },
            "author": {
                "data": {
                    "id": 16
                }
            }
        }
    }
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

