                    <h2 id="endpoints-POSTapi-v1-users--user_id--internships">POST /api/v1/users/{user}/internships
Creates a new internship posting scoped to the specified user/author, if authorized.</h2>

<p>
</p>



<span id="example-requests-POSTapi-v1-users--user_id--internships">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/users/16/internships" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"data\": {
        \"attributes\": {
            \"title\": \"Software Engineer Intern\",
            \"product\": \"architecto\",
            \"description\": \"Responsible for fullstack web development with Laravel and Vue.\",
            \"status\": \"approved\"
        }
    },
    \"author_id\": 1
}"
