                <h1 id="internship-postings">Internship postings</h1>

    

                                <h2 id="internship-postings-GETapi-v1-internships">GET /api/v1/internships
Returns a paginated list (15 per page). Each item is filtered and transformed by InternshipPostingResource.</h2>

<p>
</p>



<span id="example-requests-GETapi-v1-internships">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/internships?status=approved&amp;title=software&amp;include=author" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/internships"
);

const params = {
    "status": "approved",
    "title": "software",
    "include": "author",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};


fetch(url, {
    method: "GET",
    headers,
}).then(response =&gt; response.json());</code></pre></div>

