                    <h2 id="internship-postings-POSTapi-v1-products">POST /api/v1/internships
Creates a new internship posting from a JSON:API payload, if authorized.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>



<span id="example-requests-POSTapi-v1-products">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/products" \
    --header "Authorization: Bearer Bearer {YOUR_AUTH_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"data\": {
        \"attributes\": {
            \"title\": \"Software Engineer Intern\",
            \"product\": \"architecto\",
            \"description\": \"Responsible for fullstack web development with Laravel and Vue.\",
            \"status\": \"approved\"
        },
        \"relationships\": {
            \"author\": {
                \"data\": {
                    \"id\": 1
                }
            }
        }
    }
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/products"
);

const headers = {
    "Authorization": "Bearer Bearer {YOUR_AUTH_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "data": {
        "attributes": {
            "title": "Software Engineer Intern",
            "product": "architecto",
            "description": "Responsible for fullstack web development with Laravel and Vue.",
            "status": "approved"
        },
        "relationships": {
            "author": {
                "data": {
                    "id": 1
                }
            }
        }
    }
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

